export function bootstrapMeanCI(values, { samples = 2000, rng = Math.random, confidence = .95 } = {}) { if (!values.length) return null; const means = Array.from({ length: samples }, () => Array.from({ length: values.length }, () => values[Math.floor(rng() * values.length)]).reduce((a, b) => a + b, 0) / values.length).sort((a, b) => a - b); const tail = (1 - confidence) / 2; return { mean: values.reduce((a, b) => a + b, 0) / values.length, lower: means[Math.floor(tail * samples)], upper: means[Math.min(samples - 1, Math.ceil((1 - tail) * samples) - 1)] }; }
